# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMWC-000001",
    "name": "Wei 伟",
    "kind": "first-name",
    "meaning": "Wei (伟) is a masculine given name in Wu Chinese. Meaning: Great. The Wu reading of the same character as Mandarin Wei."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Wei")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

